class Counter {
  private count = 0          // state
  increment(): void {        // behaviour
    this.count++
  }
  get value(): number {
    return this.count
  }
}

const a = new Counter()      // two objects, separate state
const b = new Counter()
a.increment()
console.log(a.value, b.value) // 1 0

