class Counter:
    def __init__(self):
        self._count = 0        # state

    def increment(self):       # behaviour
        self._count += 1

    @property
    def value(self):
        return self._count

a, b = Counter(), Counter()    # two objects, separate state
a.increment()
print(a.value, b.value)        # 1 0

